update quizzes z set question_count = (select count(*) from quiz_questions qq join questions q on q.id = qq.question_id where qq.quiz_id = z.id and q.active) where z.topic_id in (select id from topics where subject_id = (select id from subjects where name = 'Physical Education'));
do $$ declare n int; begin
  select count(*) into n from (select topic_id, name from subtopics where topic_id in (select id from topics where subject_id = (select id from subjects where name = 'Physical Education')) group by 1, 2 having count(*) > 1) d;
  if n <> 0 then raise exception 'PE remap: % duplicate subtopic names within a topic', n; end if;
  select count(*) into n from questions where topic_id in (select id from topics where subject_id = (select id from subjects where name = 'Physical Education')) and active and subtopic_id is null;
  if n <> 0 then raise exception 'PE remap: % active questions without a subtopic', n; end if;
  select count(*) into n from questions where topic_id in (select id from topics where subject_id = (select id from subjects where name = 'Physical Education')) and active;
  if n <> 119 then raise exception 'PE remap: expected 119 active, got %', n; end if;
end $$;
